public class TextNodeTest {

    @Test
    public void nodeName_EmptyTextNode ReturnsEmptyString() {
        TextNode textNode = new TextNode("");
        assertEquals("", textNode.nodeName());
    }

    @Test
    public void nodeName_NotEmptyTextNode ReturnsCorrectText() {
        TextNode textNode = new TextNode("Hello");
        assertEquals("Hello", textNode.nodeName());
    }

    @Test
    public void text_EmptyTextNode ReturnsEmptyString() {
        TextNode textNode = new TextNode("");
        assertEquals("", textNode.text());
    }

    @Test
    public void text_NotEmptyTextNode ReturnsCorrectText() {
        TextNode textNode = new TextNode("Hello");
        assertEquals("Hello", textNode.text());
    }

    @Test
    public void textReplace_EmptyTextNodeDoesNotChange() {
        TextNode textNode = new TextNode("");
        textNode = (TextNode) textNode.text("");
        assertEquals("", textNode.text());
    }

    @Test
    public void textReplace_NotEmptyTextNodeChangesCorrectly() {
        TextNode textNode = new TextNode("Hello");
        textNode = (TextNode) textNode.text("World");
        assertEquals("World", textNode.text());
    }

    @Test
    public void getWholeText_EmptyTextNode ReturnsEmptyString() {
        TextNode textNode = new TextNode("");
        assertEquals("", textNode.getWholeText());
    }

    @Test
    public void getWholeText_NotEmptyTextNode ReturnsCorrectText() {
        TextNode textNode = new TextNode("Hello");
        assertEquals("Hello", textNode.getWholeText());
    }

    @Test
    public void isBlank_EmptyTextNode ReturnsTrue() {
        TextNode textNode = new TextNode("");
        assertTrue(textNode.isBlank());
    }

    @Test
    public void isBlank_NotEmptyTextNode ReturnsFalse() {
        TextNode textNode = new TextNode("Hello");
        assertFalse(textNode.isBlank());
    }

    @Test
    public void splitTextOffsetIsZeroReturnsCorrectText() throws IOException {
        TextNode textNode = new TextNode("Hello World");
        TextNode result = (TextNode) textNode.splitText(0);
        assertEquals("Hello ", result.text());
    }

    @Test
    public void splitTextOffsetIsAtEndReturnsEmptyString() throws IOException {
        TextNode textNode = new TextNode("Hello World");
        TextNode result = (TextNode) textNode.splitText(textNode.length());
        assertTrue(result.isBlank());
    }

    @Test
    public void clone_ReturnsSameObjectWhenNodeIsEmpty() {
        TextNode textNode = new TextNode("");
        TextNode cloned = (TextNode) textNode.clone();
        assertSame(cloned, textNode);
    }

    @Test
    public void clone_ReturnsNewTextNodeWhenNodeIsNotEmpty() {
        TextNode textNode = new TextNode("Hello");
        TextNode cloned = (TextNode) textNode.clone();
        assertNotNull(cloned);
        assertNotSame(textNode, cloned);
    }

    @Test
    public void createFromEncoded_DoesNotThrowException() throws IOException {
        String encodedText = "Hello";
        TextNode textNode = TextNode.createFromEncoded(encodedText);
        assertNotNull(textNode);
    }

    @Test
    public void normaliseWhitespace_WithMultipleSpacesReturnsCorrectString() {
        assertEquals("  ", StringUtil.normaliseWhitespace("   "));
    }

    @Test
    public void stripLeadingWhitespace_AnyInputReturnsCorrectResult() {
        assertEquals("Hello", StringUtil.stripLeadingWhitespace("   Hello"));
        assertEquals("Hello World", StringUtil.stripLeadingWhitespace("Hello World "));
    }

    @Test
    public void lastCharIsWhitespace_EmptyStringBuilder ReturnsFalse() {
        assertFalse(StringUtil.lastCharIsWhitespace(new StringBuilder()));
    }

    @Test
    public void lastCharIsWhitespace_SingleSpaceReturnsTrue() {
        assertTrue(StringUtil.lastCharIsWhitespace(new StringBuilder(" ")));
    }

    @Test
    public void lastCharIsWhitespace_MultipleSpacesReturnsTrue() {
        assertTrue(StringUtil.lastCharIsWhitespace(new StringBuilder("   ")));
    }
}
